package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class MagicLinkExpiryMinutesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property magic link expiry minutes of tenant config ")
  void test_magic_link_expiry_minutes_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class,
        () -> MagicLinkExpiryMinutesVO.tryFrom(null));
    Assertions.assertEquals(1, MagicLinkExpiryMinutesVO.from(1).getMagicLinkExpiryMinutes());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> MagicLinkExpiryMinutesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", MagicLinkExpiryMinutesVO.from(1).toString());
  }
}
